"""Write TESTBOOK.md (repo root) from the scenario files, so the two never drift.

    python scenarios/make_testbook.py           write TESTBOOK.md
    python scenarios/make_testbook.py --check   exit 1 if TESTBOOK.md is out of date
"""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import scenariolib as lib  # noqa: E402

TESTBOOK = lib.REPO_ROOT / "TESTBOOK.md"
LAYER_NAMES = {"twin": "Twin", "guardian": "Guardian", "brain": "City Brain"}

HEADER = """# Test Book

<!-- Generated by scenarios/make_testbook.py from scenarios/*.yaml. Edit the YAML files, then run
     python scenarios/make_testbook.py -->

City Brain scenarios on the mock city (`brain/mocks/city.yaml`, zones `zone-01` port .. `zone-06`
residential). Each one starts with **one command** and writes **one log file** (R2):
`logs/<ID>-<YYYYMMDD-HHMMSS>.log`, JSON lines (every observed message with its topic and time,
then a summary line with the result of each expectation). The runner prints PASS / FAIL per
expectation and exits 0 / 1. Prerequisites: broker, Brain and mocks running (`scenarios/README.md`).

| ID | Name | Layers | Duration |
|---|---|---|---|
"""


def _cell(text: object) -> str:
    return " ".join(str(text).split()).replace("|", "\\|")


def render() -> str:
    ids = lib.list_scenarios()
    scs = [lib.load_scenario(i) for i in ids]
    out = [HEADER]
    for sc in scs:
        out.append(f"| [{sc['id']}](#{sc['id'].lower()}) | {_cell(sc['name'])} | "
                   f"{', '.join(LAYER_NAMES[x] for x in sc['layers'])} | {sc['duration_s']} s |\n")
    for sc in scs:
        alias = f" (same run as {sc['alias_of']})" if sc.get("alias_of") else ""
        exp = sc["expected"]
        out.append(f"\n## {sc['id']}\n\n| Field | Value |\n|---|---|\n")
        rows = [
            ("ID", sc["id"]),
            ("Name", sc["name"] + alias),
            ("Layers involved", ", ".join(LAYER_NAMES[x] for x in sc["layers"])),
            ("Description", sc["description"]),
            ("Trigger", f"`{sc['trigger']}`"),
            ("Expected (Twin)", exp["twin"]),
            ("Expected (Guardian)", exp["guardian"]),
            ("Expected (City Brain)", exp["brain"]),
            ("How to verify", sc["how_to_verify"]),
            ("Automatic checks", "<br>".join(f"`{lib._describe(e)}`" + (" (optional)" if e.get("optional") else "")
                                             for e in sc["expect"])),
        ]
        out += [f"| {k} | {_cell(v)} |\n" for k, v in rows]
    return "".join(out)


def is_current() -> bool:
    """TESTBOOK.md matches the scenario files (line endings aside: git may check it out with CRLF)."""
    current = TESTBOOK.read_text(encoding="utf-8") if TESTBOOK.is_file() else ""
    return current.replace("\r\n", "\n") == render()


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        if not is_current():
            print("TESTBOOK.md is out of date: run python scenarios/make_testbook.py", file=sys.stderr)
            return 1
        return 0
    TESTBOOK.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {TESTBOOK.relative_to(lib.REPO_ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
